/* QR enrollment and four-session monthly tuition; no student email requested. */
let enrollmentRows=[],monthRows=[],receiptRows=[],monthCalendar=[],activityRows=[];
const monthNames=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
const monthLabel=k=>monthNames[Number(k.split('/')[1])-1]+' '+money(k.split('/')[0]);
const timeOptions=Array.from({length:72},(_,i)=>{const t=String(Math.floor(i/3)).padStart(2,'0')+':'+String(i%3*20).padStart(2,'0');return [t,t]});
async function studentEndpoint(action,data={}){const r=await fetch(URL+'/functions/v1/student-enrollment',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({action,...data})});const d=await r.json();if(!r.ok)throw Error(d.message||'ثبت‌نام در حال آماده‌سازی است؛ با دفتر هماهنگ کنید');return d}
const staffLogin=login;login=function(){authScreen('ورود هنرجو',`<p class="auth-help">نام کاربری، کد ملی شماست. ایمیل نیاز ندارید.</p>${authInput('national_id','کد ملی','text','inputmode="numeric" autocomplete="username" maxlength="10"')}${authInput('password','رمز عبور','password','autocomplete="current-password" minlength="6"')}<div class="auth-links"><button type="button" onclick="registration()">ثبت‌نام هنرجو</button><button type="button" onclick="staffLogin()">ورود مدیر، منشی و استاد</button></div><p class="sub">برای فراموشی رمز، با مدیر و احراز هویت در آموزشگاه هماهنگ کنید.</p>`,'ورود',async d=>{const a=await studentEndpoint('login',{national_id:digits(d.national_id),password:d.password});await completeLogin(a)})};
views.login=function(){return title('پرتال آوای هزاردستان','ورود با کد ملی و رمز شخصی')+`<div class="card enrollment-welcome"><img src="logo.png" width="90" height="90" alt="آوای هزاردستان"><h2>هنرجوی آوای هزاردستان هستی؟</h2><p>اطلاعاتت را ثبت کن؛ مدیر برنامهٔ کلاس و وضعیت شهریه‌ات را بررسی و تأیید می‌کند.</p><button class="primary" onclick="login()">ورود هنرجو</button> <button onclick="registration()">ثبت‌نام هنرجو</button><p><button onclick="staffLogin()">ورود کارکنان آموزشگاه</button></p></div>`};
async function registration(){try{const teachers=await studentEndpoint('teachers');if(!teachers.length)throw Error('فهرست اساتید آماده نیست');authScreen('ثبت‌نام هنرجو',`<p class="auth-help">بدون ایمیل؛ نام کاربری شما کد ملی است. زمان انتخابی پس از بررسی مدیر نهایی می‌شود.</p>${authInput('first_name','نام','text')}${authInput('last_name','نام خانوادگی','text')}${authInput('father_name','نام پدر','text')}${authInput('national_id','کد ملی','text','inputmode="numeric" maxlength="10"')}${authInput('mobile','شماره موبایل','tel','inputmode="tel"')}${authInput('birth_date','تاریخ تولد شمسی؛ مانند ۱۳۸۰/۰۵/۲۰','text')}${authInput('home_phone','تلفن منزل؛ در صورت نداشتن خط تیره','tel')}${authInput('address','نشانی منزل','text')}<label>استاد<select name="teacher_id" id="registration-teacher">${teachers.map(t=>`<option value="${t.id}">استاد ${esc(t.name)}</option>`).join('')}</select></label><label>رشته<select name="subject" id="registration-subject"></select></label><label>روز پیشنهادی<select name="weekday">${days.map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select></label><label>ساعت پیشنهادی؛ هر کلاس ۲۰ دقیقه<select name="class_time">${timeOptions.map(([v,t])=>`<option value="${v}" ${v==='19:00'?'selected':''}>${t}</option>`).join('')}</select></label>${authInput('password','رمز دلخواه؛ حداقل ۶ کاراکتر','password','minlength="6" maxlength="128" autocomplete="new-password"')}${authInput('confirmation','تکرار رمز','password','minlength="6" autocomplete="new-password"')}<label class="rules-check"><input type="checkbox" name="rules" required> قوانین آموزشگاه را خوانده‌ام و می‌پذیرم.</label><a href="portal.html#rules" target="_blank">مطالعهٔ قوانین آموزشگاه</a>`,'ثبت درخواست برای مدیر',async d=>{if(d.password!==d.confirmation)throw Error('تکرار رمز یکسان نیست');await studentEndpoint('register',{national_id:digits(d.national_id),password:d.password,details:{...Object.fromEntries(Object.entries(d).filter(([k])=>!['password','confirmation','national_id'].includes(k))),mobile:digits(d.mobile),birth_date:AcademyDates.iso(d.birth_date),rules:true}});modal.close();toast('ثبت‌نام ثبت شد. با کد ملی و رمز وارد شوید؛ منتظر تأیید مدیر باشید.');login()});const select=$('registration-teacher');const update=()=>{$('registration-subject').innerHTML=teachers.find(t=>t.id===select.value).subjects.map(s=>`<option>${esc(s)}</option>`).join('')};select.onchange=update;update();}catch(e){toast(e.message)}}
const priorReload=reload;reload=async function(){if(role!=='teacher'){[enrollmentRows,monthRows,receiptRows,monthCalendar,activityRows]=await Promise.all([api('/rest/v1/enrollment_requests?select=*&order=created_at.desc'),api('/rest/v1/monthly_tuition?select=*&order=month_key'),api('/rest/v1/monthly_receipts?select=*&order=created_at.desc'),api('/rest/v1/academy_months?select=*&order=key'),admin?api('/rest/v1/academy_activity?select=*&order=created_at.desc&limit=100'):Promise.resolve([])]);}return priorReload()};
async function enrollmentAction(op,data){return api('/rest/v1/rpc/enrollment_action','POST',{op,data})}
const oldDashboard=views.dashboard;views.dashboard=function(){return `<div class="card"><h2>درخواست‌های جدید آموزشگاه</h2><p>${money(enrollmentRows.filter(r=>r.status==='pending').length)} ثبت‌نام · ${money(receiptRows.filter(r=>r.status==='pending').length)} رسید منتظر تأیید</p><button class="primary" onclick="go('enrollments')">بررسی ثبت‌نام‌ها</button> <button onclick="go('monthly')">شهریهٔ ماهانه و رسیدها</button> <a href="registration-qr.svg" target="_blank">QR ثبت‌نام؛ دریافت برای چاپ ↗</a></div>`+oldDashboard()};
menu.push(['enrollments','♧','ثبت‌نام‌ها و گزارش فعالیت'],['monthly','▦','جدول شهریه ماهانه']);
const previousRender=render;render=function(){previousRender();if(role==='student'){const nav=$('nav');nav.innerHTML+=`<button onclick="goMonthly()">▦ جدول شهریه ماهانه</button>`;if(page==='monthly')$('content').innerHTML=views.monthly();}};
function goMonthly(){page='monthly';$('content').innerHTML=views.monthly();$('crumb').textContent='شهریهٔ ماهانه'}
views.enrollments=function(){if(!admin)return '';return title('ثبت‌نام‌ها و گزارش فعالیت','درخواست هنرجو تا تأیید نهایی، برنامه قطعی ایجاد نمی‌کند')+`<div class="card">${table(['هنرجو','درخواست کلاس','وضعیت','بررسی'],enrollmentRows.map(r=>`<tr><td>${esc(r.details.first_name+' '+r.details.last_name)}<br><small>${esc(r.national_id)}</small></td><td>استاد ${esc(teacher(r.details.teacher_id))} · ${esc(r.details.subject)}<br>${days[r.details.weekday]} ${esc(r.details.class_time)}</td><td>${esc(({pending:'منتظر تأیید',approved:'تأییدشده',rejected:'ردشده'})[r.status])}<br>${esc(r.review_note)}</td><td>${r.status==='pending'?`<button onclick="reviewEnrollment('${r.id}')">بررسی، اصلاح و تأیید</button>`:''}</td></tr>`))}</div><div class="card"><h3>گزارش فعالیت</h3>${table(['عملیات','تاریخ'],activityRows.map(a=>`<tr><td>${esc(({approve:'تأیید ثبت‌نام',reject:'رد ثبت‌نام',month:'تنظیم و انتشار شهریه',receipt_submitted:'ارسال رسید',receipt_review:'بررسی رسید'})[a.action]||a.action)}</td><td>${new Date(a.created_at).toLocaleString('fa-IR')}</td></tr>`))}</div>`};
function reviewEnrollment(id){const r=enrollmentRows.find(x=>x.id===id),d=r.details;form('بررسی و تأیید ثبت‌نام',[field('teacher_id','استاد نهایی','text',db.teachers.map(t=>[t.id,t.name])),field('subject','رشته نهایی','text'),field('weekday','روز نهایی','text',days.map((d,i)=>[i,d])),field('class_time','ساعت نهایی','text',timeOptions),field('note','توضیحات مدیر')],async v=>{await enrollmentAction('approve',{id,...v});toast('ثبت‌نام تأیید شد؛ اکنون وضعیت شهریهٔ ماه را تنظیم کنید')});for(const k of ['teacher_id','subject','weekday','class_time'])$('form').elements[k].value=d[k];$('form').elements.note.value='تأیید پس از بررسی دفتر';const info=document.createElement('div');info.className='policy';info.innerHTML=`<h3>${esc(d.first_name+' '+d.last_name)}</h3><p>نام پدر: ${esc(d.father_name)} · کد ملی: ${esc(r.national_id)}</p><p>موبایل: ${esc(d.mobile)} · تولد: ${AcademyDates.show(d.birth_date)}</p><p>${esc(d.address)} · تلفن منزل ${esc(d.home_phone)}</p><button type="button" onclick="rejectEnrollment('${id}')">رد درخواست با توضیح</button>`;$('fields').prepend(info);$('form').querySelector('[type=submit]').textContent='تأیید نهایی ثبت‌نام'}
async function rejectEnrollment(id){const note=prompt('دلیل رد درخواست');if(!note)return;try{await enrollmentAction('reject',{id,note});modal.close();await reload()}catch(e){toast(e.message)}}
function tuitionGrid(list){return table(['ماه','جلسهٔ اول','جلسهٔ دوم','جلسهٔ سوم','جلسهٔ چهارم','مانده','اقدام'],list.map(t=>{const pending=receiptRows.filter(r=>r.tuition_id===t.id&&r.status==='pending');return `<tr><td><strong>${monthLabel(t.month_key)}</strong></td>${t.dates.map((date,i)=>`<td><div class="tuition-slot ${t.paid[i]?'settled':pending.some(p=>p.slots.includes(i+1))?'waiting':'unpaid'}"><b>${AcademyDates.show(date)}</b><span>${t.paid[i]?'پرداخت‌شده':pending.some(p=>p.slots.includes(i+1))?'در انتظار تأیید':'پرداخت‌نشده'}</span><small>۵۰۰٬۰۰۰ تومان</small></div></td>`).join('')}<td>${money(t.paid.filter(v=>!v).length*500000)} تومان</td><td>${role==='student'&&t.paid.some(v=>!v)?`<button onclick="payMonth('${t.id}')">پرداخت</button>`:admin?`<button onclick="editMonth('${t.student_id}','${t.month_key}')">تنظیم مدیر</button>`:'تسویه'}<small>${esc(t.note)}</small></td></tr>`}))}
views.monthly=function(){if(role==='student'&&!db.students.some(s=>s.user_id===uid))return '<div class="card"><h2>ثبت‌نام در انتظار بررسی مدیر است</h2><p>پس از تأیید مدیر و تنظیم شهریه، جدول شما نمایش داده می‌شود.</p></div>';return title('جدول شهریهٔ ماهانه','از آذر ۱۴۰۵ · هر ماه ۴ جلسهٔ ۲۰ دقیقه‌ای · هر جلسه ۵۰۰ هزار تومان',admin?btn('تنظیم شهریهٔ هنرجو','editMonth()'):'')+(admin?`<div class="card"><h3>ثبت شهریه برای هنرجویان قبلی</h3><p>هنرجو و ماه را انتخاب کنید و چهار جلسه را مستقل مشخص کنید؛ فقط پس از ثبت نهایی، جدول به هنرجو نمایش داده می‌شود.</p><button onclick="configureBank()">تنظیم شماره کارت و حساب</button></div>`:'')+(monthRows.length?admin?db.students.map(s=>`<div class="card"><h3>${esc(full(s))}</h3>${tuitionGrid(monthRows.filter(t=>t.student_id===s.id))}</div>`).join(''):`<div class="card">${tuitionGrid(monthRows)}</div>`:'<div class="card empty">جدول تأییدشده‌ای برای نمایش وجود ندارد.</div>')+receiptTable()};
function editMonth(sid,key){if(!admin)return;form('تنظیم و انتشار شهریهٔ ماه',[field('student_id','هنرجو','text',studentsOpt()),field('month_key','ماه شمسی','text',monthCalendar.map(m=>[m.key,monthLabel(m.key)])),...[1,2,3,4].map(i=>field('p'+i,'جلسهٔ '+money(i),'text',[[false,'پرداخت‌نشده'],[true,'پرداخت‌شده']])),field('note','توضیح یا مرجع دفتر')],async d=>{await enrollmentAction('month',{student_id:d.student_id,month_key:d.month_key,paid:[1,2,3,4].map(i=>d['p'+i]==='true'),note:d.note});toast('جدول تأیید و برای هنرجو منتشر شد')});if(sid)$('form').elements.student_id.value=sid;if(key)$('form').elements.month_key.value=key;const apply=()=>{const f=$('form'),t=monthRows.find(x=>x.student_id===f.elements.student_id.value&&x.month_key===f.elements.month_key.value);[1,2,3,4].forEach(i=>f.elements['p'+i].value=String(t?.paid[i-1]||false));f.elements.note.value=t?.note||'تطبیق با دفتر آموزشگاه'};$('form').elements.student_id.onchange=apply;$('form').elements.month_key.onchange=apply;apply();$('form').querySelector('[type=submit]').textContent='تأیید و نمایش به هنرجو'}
function payMonth(id){const t=monthRows.find(x=>x.id===id);authScreen('پرداخت '+monthLabel(t.month_key),`<p>جلسات موردنظر را انتخاب کنید؛ هر جلسه ۵۰۰ هزار تومان.</p>${t.paid.map((p,i)=>p?'':`<label class="rules-check"><input type="checkbox" name="slot${i+1}" checked> جلسه ${money(i+1)} · ${AcademyDates.show(t.dates[i])}</label>`).join('')}<label>روش پرداخت<select name="method" id="monthly-method"><option value="card">دیدن شماره کارت</option><option value="bank">واریز به حساب / شبا</option><option value="office">پرداخت در آموزشگاه</option></select></label><div id="monthly-bank"></div>${authInput('reference','کد رهگیری واریز یا شماره رسید آموزشگاه','text','minlength="4" maxlength="64"')}<p class="auth-help">در پرداخت حضوری، شماره رسید را از آموزشگاه بگیرید. ثبت رسید تا تأیید مدیر، جلسه را پرداخت‌شده نمی‌کند.</p>`,'ارسال رسید برای تأیید مدیر',async d=>{const slots=[1,2,3,4].filter(i=>d['slot'+i]);if(!slots.length)throw Error('حداقل یک جلسه انتخاب کنید');if(d.method==='card'&&!bankAccount?.card||d.method==='bank'&&!bankAccount?.iban)throw Error('مشخصات حساب تکمیل نشده؛ با دفتر هماهنگ کنید');await enrollmentAction('submit',{id,slots,method:d.method,reference:digits(d.reference)});modal.close();await reload();goMonthly();toast('رسید برای بررسی مدیر ثبت شد')});const update=()=>{const v=$('monthly-method').value;$('monthly-bank').innerHTML=v==='office'?'<p class="policy">پس از پرداخت در آموزشگاه، شماره رسید دریافت کنید.</p>':`<div class="policy"><b>${esc(bankAccount?.holder||'حساب هنوز تنظیم نشده')}</b><p dir="ltr">${esc(v==='card'?bankAccount?.card||'—':bankAccount?.iban||'—')}</p></div>`};$('monthly-method').onchange=update;update();}
function receiptTable(){return `<div class="card"><h3>رسیدهای شهریهٔ ماهانه</h3>${table(['هنرجو و ماه','جلسات و مبلغ','روش و کد رهگیری','وضعیت','بررسی'],receiptRows.map(r=>{const t=monthRows.find(t=>t.id===r.tuition_id),s=db.students.find(s=>s.id===t?.student_id);return `<tr><td>${esc(s?full(s):'')}<br>${t?monthLabel(t.month_key):''}</td><td>${r.slots.map(money).join('، ')}<br>${money(r.amount)} تومان</td><td>${({card:'کارت',bank:'حساب',office:'آموزشگاه'})[r.method]}<br>${esc(r.reference)}</td><td>${paymentStatus(r)}<br>${esc(r.note)}</td><td>${admin&&r.status==='pending'?`<button onclick="reviewMonthly('${r.id}',true)">تأیید</button> <button onclick="reviewMonthly('${r.id}',false)">رد</button>`:''}</td></tr>`}).join(''))}</div>`}
async function reviewMonthly(id,yes){const note=yes?'دریافت مبلغ توسط مدیر بررسی شد':prompt('دلیل رد رسید');if(!note)return;try{await enrollmentAction('review',{id,status:yes?'approved':'rejected',note});await reload()}catch(e){toast(e.message)}}
const oldPortal=views.portal;views.portal=function(){const r=enrollmentRows.find(r=>r.user_id===uid);if(r?.status!=='approved'&&!db.students.some(s=>s.user_id===uid))return `<div class="card"><h2>${r?.status==='rejected'?'ثبت‌نام نیاز به پیگیری دارد':'در انتظار تأیید مدیر'}</h2><p>${esc(r?.review_note||'مدیر، استاد و ساعت کلاس را بررسی می‌کند و سپس جدول شهریه شما فعال می‌شود.')}</p></div>`;return oldPortal()+`<div class="card"><h2>شهریهٔ چهارجلسه‌ای</h2>${tuitionGrid(monthRows)}</div>`};
render();if(location.hash==='#register')registration();
views.payments=views.monthly;
const legacyCredit=credit,legacyEligible=eligible;
credit=function(s){const rows=monthRows.filter(t=>t.student_id===s.id);if(!rows.length)return legacyCredit(s);return rows.reduce((n,t)=>n+t.paid.filter((p,i)=>p&&!db.sessions.some(c=>c.student_id===s.id&&c.starts_at.slice(0,10)===t.dates[i]&&['completed','absent'].includes(c.status))).length,0)};
eligible=function(s){const today=AcademyDates.today(),rows=monthRows.filter(t=>t.student_id===s.id);if(!rows.length)return legacyEligible(s);const next=rows.flatMap(t=>t.dates.map((d,i)=>({date:d,paid:t.paid[i]}))).filter(x=>x.date>=today).sort((a,b)=>a.date.localeCompare(b.date))[0];return !!next?.paid};
const enrollmentTotalPaid=totalPaid;totalPaid=function(s){if(!monthRows.some(t=>t.student_id===s.id))return enrollmentTotalPaid(s);return monthRows.filter(t=>t.student_id===s.id).reduce((n,t)=>n+t.paid.filter(Boolean).length*500000,0)};
